/* v1.1 review build: local-only investigation and bounded rule inference. */
const INV_DEFAULTS={heTab:'fasebook',heSearch:'',heSearchSubmitted:false,heSearchResult:'',hePane:'timeline',hePlace:[],heClips:[],heVerdict:false,heFeedback:'',heChat:0,heShared:false,linProofs:[],linFeedback:'',linRecordPage:0,linSafetyFeedback:'',linGrounded:false};
const HE_CLUES={park:{title:'11月7日・景點打卡',text:'2012／11／07　15:16　林心愛　安平舊街小廣場　台南市安平區。'},meal:{title:'11月7日・晚餐打卡',text:'2012／11／07　19:24　林心愛　楠巷燒肉　嘉義市東區。'},roster:{title:'99學年度・系學會紀錄',text:'語言文本與文化學系・99學年度系學會。文書：林心愛、吳以晴、陳映竹。資料歸檔：2011年6月。'},honor:{title:'101學年度・文學系榮譽榜',text:'文學系101學年度學生文學獎，散文組優選：林心愛。公告日期：2012年10月26日。'},sender:{title:'詛咒信的上一位傳送者',text:'周柏廷：「我也是收到別人轉的。」何稻禾：「我們認識嗎？這個原本是誰寫的？」周柏廷：「之前加過好友的吧。我也不知道最早是誰，抱歉。」'}};
const HE_CHAT=[['何稻禾','秋，我翻到學姐的舊貼文，還查了學校的紀錄。兩個系都有林心愛這個名字。'],['沈秋','兩個系？先別只靠名字判斷，會不會同名？'],['何稻禾','對，所以我把原文都留了。還有兩則打卡，我一開始以為是同一段行程，點開地址才發現一個台南、一個嘉義。'],['沈秋','跨城市也可能是搭車過去。先問學姐，不要幫她把經過補起來。'],['何稻禾','嗯，還查到之前轉信給我的人。不是學姐，是個不熟的人，對方也說自己收到才轉。資料一起傳給你。'],['沈秋','收到了，謝謝。等學姐來，我拿這些問她。你也先別去看窗外。']];
const LIN_PROOFS=[{id:'attendance',title:'語言文本與文化學系・課堂簽到',text:'2012／11／06　星期二　第3、4節\n文字與閱讀研討\n林心愛：簽到；當堂短評一份。\n授課教師：賴老師。'}, {id:'essay',title:'林心愛帶來的文學系課堂習作',text:'2012／11／06　星期二　第3、4節\n散文專題\n署名：林心愛。頁邊寫著分組討論的座位與發言順序。\n學姐說，那堂課的討論與習作都是自己親自完成的。'}, {id:'names',title:'何稻禾傳來的兩筆姓名',text:'語言文本與文化學系／99學年度系學會文書：林心愛。\n文學系／101學年度文學獎散文組優選：林心愛。'}, {id:'places',title:'台南與嘉義的兩則打卡',text:'2012／11／07　15:16\n安平舊街小廣場，台南市安平區。\n2012／11／07　19:24\n楠巷燒肉，嘉義市東區。'}];
const LIN_OBSERVATIONS=[['最早的一頁','一開始，是轉開視線以後才留著的一塊顏色。等了一會兒就沒有了。我回去看，想知道剛才看的是什麼。'],['後來補寫的紀錄','我又去看了幾次。後來不只是輪廓。我開始記得另一間教室的課，有些名字以前明明沒聽過。那裡的人說最近常和我同組；問更早的事，他們卻說想不起來。'],['某次關簾後的紀錄','那次我沒有再打開。之後一段時間，沒有再多出我不記得何時開始的談話。已經記得的那些課沒有消失。我不確定是不是窗簾的關係。']];
function heClip(id){return HE_CLUES[id]?`<button class="he-clip ${state.heClips.includes(id)?'saved':''}" data-act="he:clip:${id}">${state.heClips.includes(id)?'✓ 已保存原文':'保存原文到調查夾'}</button>`:'';}
function hePost(name,date,body,extra='',clue=''){return `<article class="fb-post"><header><span class="fb-initial" aria-hidden="true">林</span><div><b>${esc(name)}</b><small>${esc(date)} · 朋友</small></div></header><p>${body}</p>${extra}${clue?heClip(clue):''}<footer>讚 · 留言 · 分享</footer></article>`;}
function heLocation(id,title,city,address){const open=state.hePlace.includes(id);return `<button class="fb-checkin" data-act="he:place:${id}"><span aria-hidden="true">⌖</span><span><b>${title}</b><small>地標 · ${open?'收起地點資訊':'查看地點資訊'}</small></span></button>${open?`<div class="fb-address"><b>${city}</b><p>${address}</p>${heClip(id)}</div>`:''}`;}
function heTimeline(){return `<div class="fb-profile"><span class="fb-profile-picture">林</span><div><h2>林心愛</h2><p>朋友 · 生活時報</p></div></div><nav class="fb-profile-tabs"><b>動態時報</b><span>關於</span><span>朋友</span></nav><div class="fb-posts">${hePost('林心愛','2012年11月7日 19:24','走了一整天，總算吃到晚餐。還好有先訂位。',heLocation('meal','楠巷燒肉','嘉義市東區','店家地點資訊／嘉義市東區・楠巷燒肉'))}${hePost('林心愛','2012年11月7日 15:16','終於出來走走，回去再面對論文。',heLocation('park','安平舊街小廣場','台南市安平區','地標資訊／台南市安平區・安平舊街小廣場'))}${hePost('林心愛','2012年11月3日 21:08','今年系學會活動的海報清楚多了，至少一眼找得到時間。辛苦這屆了。')}${hePost('林心愛','2012年10月28日 23:41','題目明明是從學校出發，結果我在學校坐了一整天，只多寫了三行。')}${hePost('林心愛','2012年10月17日 18:02','本來只是想確認一下。寫下來再回去看，反而有更多需要確認的地方。')}</div>`;}
function heMessages(){return `<section class="fb-messages"><h2>訊息</h2><div class="fb-message-person"><span class="fb-initial stranger">周</span><b>周柏廷</b><small>不熟悉的聯絡人</small></div><p class="fb-message-date">2012年11月8日 17:14</p><div class="fb-message-bubble">不好意思，突然傳這個。我也是收到別人轉的，上面說看了要再傳出去。我不知道真的假的……</div><details class="fb-forwarded"><summary>轉傳內容／353詛咒信</summary><div>${esc(parts.join('\n\n'))}</div></details><div class="fb-message-self">我們認識嗎？這個原本是誰寫的？</div><div class="fb-message-bubble">之前加過好友的吧。我也不知道最早是誰，抱歉。</div>${heClip('sender')}</section>`;}
function heCampus(){return `<div class="campus-site"><header><small>CHENGHAI HUMANITIES UNIVERSITY</small><h2>誠海人文大學</h2><p>2012年・校園系所介紹與歷年紀錄</p></header><nav>${btn('he:campus:roster','語言文本與文化學系',state.hePane==='honor'?'secondary':'primary')}${btn('he:campus:honor','文學系',state.hePane==='honor'?'primary':'secondary')}</nav>${heCampusSearch()}${state.hePane==='directory'?heCampusResults():state.hePane==='honor'?`<article><p>首頁 › 文學系 › 榮譽榜</p><h3>101學年度學生文學獎</h3><p>公告日期：2012年10月26日</p><table><tr><th>組別</th><th>獎項</th><th>姓名</th></tr><tr><td>散文</td><td>優選</td><td>林心愛</td></tr><tr><td>新詩</td><td>佳作</td><td>葉庭宇</td></tr></table><p>恭喜本系獲獎同學。領獎事宜請洽系辦。</p>${heClip('honor')}</article>`:`<article><p>首頁 › 語言文本與文化學系 › 系學會歷年紀錄</p><h3>99學年度系學會活動彙整</h3><p>資料歸檔：2011年6月</p><table><tr><th>組別</th><th>成員</th></tr><tr><td>會長</td><td>徐以辰</td></tr><tr><td>副會長</td><td>高宛庭</td></tr><tr><td>文書</td><td>林心愛、吳以晴、陳映竹</td></tr><tr><td>活動</td><td>鄭子謙、周雅文</td></tr><tr><td>總務</td><td>黃品安、蔡宜珊</td></tr><tr><td>器材</td><td>許承宇</td></tr><tr><td>公關</td><td>江予晴</td></tr></table><p>以上為99學年度留存資料。101學年度活動請見當屆公告。</p>${heClip('roster')}<hr><h3>系所簡介</h3><p>語言、文本閱讀與文化研究。課程與學生事務由本系辦公室辦理。</p></article>`}<footer>誠海人文大學・校園資訊服務</footer></div>`;}
function heFolder(){return `<section class="he-folder"><h2>調查夾</h2><p>已保存 ${state.heClips.length}／5 份。</p>${state.heClips.map(id=>`<article><h3>${HE_CLUES[id].title}</h3><p>${HE_CLUES[id].text}</p></article>`).join('')||'<p>尚未保存資料。可在貼文地點、私訊與校園紀錄下保存原文。</p>'}${state.heClips.length===5?`<h3>目前可以告訴沈秋什麼？</h3>${['兩個城市不同，已經足以證明其中一個林心愛不是真的','兩個系所的同名紀錄與生活資料值得向本人核對','周柏廷傳過詛咒信，所以另一個林心愛是周柏廷'].map((t,i)=>btn('he:verdict:'+i,t,'choice')).join('')}`:''}<p class="feedback" role="status">${esc(state.heFeedback)}</p>${state.heVerdict?btn('he:tab:fine','開啟Fasebook訊息，把原文傳給沈秋 →'):''}</section>`;}
function heMessengerContacts(){return `<aside class="fb-contact-rail" aria-label="何稻禾的聊天聯絡人"><h3>聊天</h3><div class="contact">${avatar('沈秋')}<button class="contact-open" data-act="he:tab:fine" ${state.heVerdict?'':'disabled'}><span>沈秋<small>${state.heVerdict?'傳送查核資料':'尚未整理完資料'}</small></span><i class="fb-online">●</i></button></div><div class="contact"><span class="fb-placeholder-avatar">周</span><button class="contact-open" data-act="he:pane:messages"><span>周柏廷<small>訊息</small></span></button></div><div class="contact"><span class="fb-placeholder-avatar">林</span><button class="contact-open" data-act="he:pane:timeline"><span>林心愛<small>查看動態時報</small></span></button></div><button class="fb-close-contacts" data-act="fb:contacts">收起聯絡人</button></aside>`;}
function heFine(){const n=state.heChat,next=HE_CHAT[n],body=HE_CHAT.slice(0,n).map(([name,text])=>`<div class="message ${name==='何稻禾'?'self':''}"><div class="sender">${avatar(name)}${named(name)}</div><div class="bubble">${esc(text)}</div></div>`).join('')+(n>=5?'<div class="he-attachments">▤ 已傳送：景點、餐廳、兩系紀錄與轉傳來源，共5份原文</div>':'')+(next&&next[0]!=='何稻禾'?'<p class="typing">沈秋正在輸入訊息……</p>':''),control=next?(next[0]==='何稻禾'?btn('he:send','傳送：'+esc(next[1])+' ↵','reply'):'<p>等待回覆……</p>'):btn('he:return','回到沈秋，等學姐抵達353 →');return messengerShell({owner:'何稻禾',contact:'沈秋',contacts:heMessengerContacts(),content:heTimeline(),body,control,thread:'shen',homeAction:'he:pane:timeline',messagesAction:'he:tab:fine'});}
function heFasebook(){const messages=state.hePane==='messages';return messengerShell({owner:'何稻禾',contact:'周柏廷',contacts:heMessengerContacts(),content:heTimeline(),body:messages?heMessages():'',control:messages?btn('he:pane:timeline','回到林心愛的動態時報','reply'):'',thread:'zhou',chat:messages,homeAction:'he:pane:timeline',messagesAction:'he:pane:messages'});}
function investigation(){return `<section class="he-browser"><div class="he-browser-chrome"><span>‹　›　↻</span><span>${state.heTab==='campus'?'campus.chenghai.edu/department':state.heTab==='folder'?'本機調查紀錄':'www.fasebook.com/'+(state.heTab==='fine'?'messages':'lin.xinai')}</span></div><nav class="he-browser-tabs">${[['fasebook','Fasebook'],['campus','校園系所介紹'],['folder','調查夾 '+state.heClips.length+'/5'],['fine','Fasebook訊息']].map(([k,n])=>btn('he:tab:'+k,n,k===state.heTab?'primary':'secondary',k==='fine'&&!state.heVerdict)).join('')}</nav>${state.heTab==='campus'?heCampus():state.heTab==='folder'?heFolder():state.heTab==='fine'?heFine():heFasebook()}</section>`;}

function recordCompare(){return `<section class="lin-evidence workspace"><span class="eyebrow">2012年 ／ 沈秋・353</span><h2>哪兩份資料能直接詢問「同一時段的兩段經歷」？</h2><p>選取兩份，再向學姐提出。</p><div class="lin-record-grid">${LIN_PROOFS.map(p=>`<button class="lin-record ${state.linProofs.includes(p.id)?'picked':''}" data-act="lin:proof:${p.id}" aria-pressed="${state.linProofs.includes(p.id)}"><h3>${p.title}</h3><p>${esc(p.text)}</p></button>`).join('')}</div><p class="feedback" role="status">${esc(state.linFeedback)}</p>${btn('lin:present','向學姐核對這兩份紀錄','primary',state.linProofs.length!==2)}</section>`;}
function linSafety(){const d=LIN_OBSERVATIONS[state.linRecordPage];return `<section class="vn-stage lin-safety"><img class="vn-backdrop" src="assets/window-w2-closed.webp" alt="353閉合的紅色窗簾"><div class="lin-note"><nav>${LIN_OBSERVATIONS.map((r,i)=>btn('lin:note:'+i,r[0],state.linRecordPage===i?'primary':'secondary')).join('')}</nav><h3>${d[0]}</h3><p>${esc(d[1])}</p></div><div class="vn-dialogue"><div class="vn-speaker">${named('林心愛')}</div><p>你剛剛是在這裡問我，還是……算了。把窗簾打開，你也看一次，就知道我在說哪個人。</p><p class="lin-question">依照目前紀錄，現在最有依據的做法是？</p>${['打開窗簾，讓兩邊一起確認','告訴學姐，對面那個人就是她自己','維持窗簾閉合，先和學姐核對眼前的事物'].map((t,i)=>btn('lin:safe:'+i,t,'choice')).join('')}<p class="feedback" role="status">${esc(state.linSafetyFeedback)}</p></div></section>`;}
function investigationAction(id){if(id.startsWith('review:')){reviewJump(id.slice(7));return true;}if(id==='reviewmenu'){modal='review';renderModal();return true;}if(id.startsWith('he:')){const a=id.slice(3);if(a==='tab:fine'||a==='pane:messages'){state.fbChatMinimized=false;state.fbContactsOpen=false;}if(a==='pane:timeline'){state.fbChatMinimized=true;state.fbMessagesFull=false;state.fbContactsOpen=false;}if(state.phase!=='investigation')return true;if(a==='search'){const input=document.querySelector('#campus-name-search');state.heSearch=String(input?input.value:state.heSearch||'').trim().slice(0,40);state.heSearchSubmitted=true;state.heSearchResult=state.heSearch.replace(/\s/g,'');state.hePane='directory';state.heTab='campus';}else if(a.startsWith('tab:')){const tab=a.slice(4);if(!['fasebook','campus','folder','fine'].includes(tab)||tab==='fine'&&!state.heVerdict)return true;state.heTab=tab;}else if(a.startsWith('pane:')){state.hePane=a.slice(5);state.heTab='fasebook';}else if(a.startsWith('campus:')){state.hePane=a.slice(7);state.heTab='campus';}else if(a.startsWith('place:')){const key=a.slice(6);if(!['meal','park'].includes(key))return true;state.hePlace=state.hePlace.includes(key)?state.hePlace.filter(x=>x!==key):state.hePlace.concat(key);}else if(a.startsWith('clip:')){const key=a.slice(5);if(!HE_CLUES[key]||['meal','park'].includes(key)&&!state.hePlace.includes(key))return true;if(!state.heClips.includes(key))state.heClips.push(key);}else if(a.startsWith('verdict:')){if(state.heClips.length!==5)return true;if(a==='verdict:1'){state.heVerdict=true;state.heFeedback='先把資料交給秋。';}else state.heFeedback='好像不太對……';}else if(a==='send'){if(!state.heVerdict||HE_CHAT[state.heChat]?.[0]!=='何稻禾')return true;state.heChat++;}else if(a==='return'){if(state.heChat!==HE_CHAT.length)return true;state.heShared=true;startVN('heBack');return true;}save();render();return true;}
 if(id.startsWith('lin:proof:')){if(state.phase!=='recordCompare')return true;const key=id.slice(10);if(!LIN_PROOFS.some(p=>p.id===key))return true;if(state.linProofs.includes(key))state.linProofs=state.linProofs.filter(x=>x!==key);else if(state.linProofs.length<2)state.linProofs.push(key);state.linFeedback='';save();render();return true;}
 if(id==='lin:present'){if(state.phase!=='recordCompare'||state.linProofs.length!==2)return true;if(['attendance','essay'].every(x=>state.linProofs.includes(x))){startVN('linConflict');return true;}state.linFeedback='好像不太對……';save();render();return true;}
 if(id.startsWith('lin:note:')){if(state.phase==='linSafety'){state.linRecordPage=Math.max(0,Math.min(2,+id.slice(9)||0));save();render();}return true;}
 if(id.startsWith('lin:safe:')){if(state.phase!=='linSafety')return true;if(id==='lin:safe:2'){state.linGrounded=true;startVN('linAnchor');return true;}state.linSafetyFeedback='這樣真的可以嗎......？';save();render();return true;}return false;}
function scheduleInvestigation(){if(state.phase!=='investigation'||state.heTab!=='fine'||!state.heVerdict)return;const n=state.heChat,next=HE_CHAT[n];if(!next||next[0]==='何稻禾')return;once('he-fine:'+n,MESSAGE_DELAY,()=>{if(state.phase!=='investigation'||state.heChat!==n)return;state.heChat++;save();render();});}
function reviewMenu(){return `<h2>測試章節選單</h2><p>只存在於這份ZIP。跳章會建立一份準備好的當次進度；結局收藏另行保留。</p>${btn('review:he','何稻禾・網頁調查','choice')}${btn('review:lin','林心愛・兩套經歷與規則應對','choice')}${btn('review:manuscript','原有草稿指認謎題','choice')}${btn('review:start','從最初開場開始','choice')}`;}
function reviewJump(target){restartGame();if(target==='start')return;state.begun=true;state.teacherRead=state.ack=state.submitted=true;state.posterDone=state.posterReceipt=true;state.posterBriefCount=3;state.c1=state.c2=2;state.anUnlocked=true;state.progress={teacher:9,ah:8,an:8};state.hidden=state.destroyed=state.coverClosed=true;state.warm=true;state.copy=2;state.line=6;state.evidence=['materials','letters','copies','order','rail','gap'];if(target==='he'){startVN('heIntro');return;}state.hePlace=['meal','park'];state.heClips=Object.keys(HE_CLUES);state.heVerdict=state.heShared=true;state.heChat=HE_CHAT.length;if(target==='lin'){startVN('meeting');return;}if(target==='manuscript'){phase('draftCompare');return;}phase('desktop');}
function investigationJournal(){if(!state.heShared&&!state.linGrounded)return '';return `<section class="source"><h2>補充查核・何稻禾留下的原文</h2>${state.heClips.map(id=>`<article><h3>${HE_CLUES[id].title}</h3><p>${HE_CLUES[id].text}</p></article>`).join('')}${state.linGrounded?'<h3>353當面的核對</h3><p>學姐親口表示自己記得同時段的兩堂課。窗簾保持閉合後，新的談話暫時沒有再增加；已經存在的另一套記憶並未消失。</p>':''}</section>`;}

function heCampusSearch(){return `<form class="campus-search" id="campus-search-form"><label for="campus-name-search">站內搜尋</label><input id="campus-name-search" type="search" maxlength="40" placeholder="輸入姓名" value="${esc(state.heSearch)}" autocomplete="off"><button type="submit" class="secondary">搜尋</button></form>`;}
const CAMPUS_ROSTER=[['會長','徐以辰'],['副會長','高宛庭'],['文書','林心愛'],['文書','吳以晴'],['文書','陳映竹'],['活動','鄭子謙'],['活動','周雅文'],['總務','黃品安'],['總務','蔡宜珊'],['器材','許承宇'],['公關','江予晴']];
function heCampusResults(){const q=state.heSearchResult;if(!q)return '<article><h3>站內搜尋</h3><p>請輸入姓名。</p></article>';const roster=CAMPUS_ROSTER.filter(([,n])=>n.includes(q)),honors=[['林心愛','散文組優選'],['葉庭宇','新詩組佳作']].filter(([n])=>n.includes(q));return `<article><p>首頁 › 站內搜尋</p><h3>搜尋：${esc(state.heSearch)}</h3><p>找到 ${roster.length+honors.length} 筆資料。</p>${roster.map(([role,n])=>`<article class="campus-result"><h4>${esc(n)}・99學年度系學會</h4><p>語言文本與文化學系／${role}／資料歸檔2011年6月</p>${btn('he:campus:roster','開啟歷年紀錄','secondary')}</article>`).join('')}${honors.map(([n,award])=>`<article class="campus-result"><h4>${esc(n)}・101學年度學生文學獎</h4><p>文學系／${award}／2012年10月26日</p>${btn('he:campus:honor','開啟榮譽榜','secondary')}</article>`).join('')}${!roster.length&&!honors.length?'<p>沒有符合的資料。</p>':''}</article>`;}
document.addEventListener('input',e=>{if(e.target.id==='campus-name-search'){state.heSearch=e.target.value.slice(0,40);save();}});
document.addEventListener('submit',e=>{if(e.target.id==='campus-search-form'){e.preventDefault();act('he:search');}});

